Running Python code interactively: # Find nSamples, nPatches in [0, 0x7ffe] where allocation size wraps to small value
# allocation = ((nSamples+1)*(nPatches+1)*8) mod 2^32
# We want allocation small (so small buffer allocated) but data index range large

best = []
for ns in range(0x7ffe, 0, -1):
    for np in range(0x7ffe, 0, -1):
        alloc = ((ns+1)*(np+1)*8) & 0xFFFFFFFF
        # data max index = ns*np + ns (nSet up to np, nField up to ns)
        maxidx = np*ns + ns
        if alloc < 1000000 and maxidx > alloc//8:
            best.append((alloc, ns, np, maxidx))
            if len(best) > 20:
                break
    if len(best) > 20:
        break
for b in best[:20]:
    print(b)

